33	function paint(canvas, asset, frames, scale, elapsed, state) {
34	  const [width, height] = display.cell;
35	  const frame = statusFrame(state, elapsed, motion.matches);
36	  const context = canvas.getContext('2d', { willReadFrequently: true });
37	  context.imageSmoothingEnabled = display.filter !== 'nearest';
38	  context.fillStyle = panel;
39	  context.fillRect(0, 0, canvas.width, canvas.height);
40	  if (asset.available && asset.width === width * frames && asset.height === height) {
41	    context.drawImage(asset.image, frame * width, 0, width, height, 0, 0, width * scale, height * scale);
42	  }
43	  return frame;
44	}
