46	async function makeCell(consumer, state, scale, elapsed = 0, track = true) {
47	  const descriptor = consumers[consumer](state);
48	  const asset = await imageFor(descriptor.path);
49	  const node = document.createElement('div');
50	  node.className = `cell ${consumer === 'compactStatus' ? 'compact' : ''}`;
51	  const glyph = document.createElement('span'); glyph.className = 'glyph';
52	  const label = document.createElement('span'); label.textContent = descriptor.label;
53	  node.append(glyph, label);
54	  const info = { consumer, state, scale, descriptor, asset: { ...asset, image: undefined }, node, canvas: null, frame: 0 };
55	  if (asset.available) {
56	    const canvas = document.createElement('canvas');
57	    canvas.width = display.cell[0] * scale; canvas.height = display.cell[1] * scale;
58	    canvas.setAttribute('aria-label', `${descriptor.label} icon`);
59	    info.canvas = canvas; info.frame = paint(canvas, asset, descriptor.frames, scale, elapsed, state);
60	    info.geometryMatches = asset.width === display.cell[0] * descriptor.frames && asset.height === display.cell[1];
61	    glyph.append(canvas);
62	    if (!info.geometryMatches) { const warning = document.createElement('span'); warning.className = 'missing'; warning.textContent = 'Wrong sheet size'; node.append(warning); }
63	  } else {
64	    glyph.classList.add('missing'); glyph.textContent = 'Missing asset';
65	  }
66	  if (track) cells.push(info);
67	  return info;
68	}
